steps.code:
song_release_years = []
for song in songs_in_library:
    details = apis.spotify.show_song(song_id=song["song_id"])
    if details:
        song_release_years.append(details["release_date"][:4])
print("Song library release years collected.")

count = sum(1 for y in song_release_years if y in ["2022", "2023"])
for album in albums_in_library:
    if album["release_date"][:4] in ["2022", "2023"]:
        count += len(album["song_ids"])
print(count)

