access_token = login_res['access_token']

liked_song_artist_ids = set()
page = 0
while True:
    songs = apis.spotify.show_liked_songs(access_token=access_token, page_index=page, page_limit=20)
    if not songs:
        break
    for song in songs:
        for artist in song['artists']:
            liked_song_artist_ids.add(artist['id'])
    page += 1

print(f"Found artist IDs from liked songs: {liked_song_artist_ids}")

