for song in liked_songs:
    apis.spotify.download_song(song_id=song["song_id"], access_token=access_token)
print("All liked songs downloaded.")

downloaded_songs_list = []
page_index = 0
while True:
    page = apis.spotify.show_downloaded_songs(access_token=access_token, page_index=page_index, page_limit=20)
    if not page:
        break
    downloaded_songs_list.extend(page)
    page_index += 1
downloaded_song_ids = {s["song_id"] for s in downloaded_songs_list}
print(f"Already downloaded: {len(downloaded_song_ids)}")

