transactions_to_friend_emails = {t['transaction_id'] for t in all_transactions if t['sender']['email'] in friend_emails or t['receiver']['email'] in friend_emails}
print(f"Found {len(transactions_to_friend_emails)} transactions to/from friends this month.")
# Check first few
for t in all_transactions[:3]:
    print(t['transaction_id'], t['sender']['email'], t['receiver']['email'], t['liked'])

friends = []
page_index = 0
while True:
    page = apis.venmo.search_friends(access_token=venmo_access_token, page_index=page_index, page_limit=20)
    if not page:
        break
    friends.extend(page)
    if len(page) < 20:
        break
    page_index += 1

friend_emails = {f['email'] for f in friends}
print(f"Total friends: {len(friend_emails)}")
print(f"Friends: {friend_emails}")

