for pl in all_playlists:
    pl_details = apis.spotify.show_playlist(playlist_id=pl["playlist_id"], access_token=access_token)
    songs = pl_details.get("songs", [])
    if not songs:
        continue

    best_song_id = None
    max_plays = -1

    for s in songs:
        s_info = apis.spotify.show_song(song_id=s["id"])
        if s_info["play_count"] > max_plays:
            max_plays = s_info["play_count"]
            best_song_id = s["id"]

    if best_song_id is not None:
        most_played_song_ids.append(best_song_id)

print(f"Found {len(most_played_song_ids)} songs: {most_played_song_ids}")

